describe('ARIA Landmarks - Page Regions', () => {
  beforeEach(() => {
    cy.visit('/');
    cy.injectAxe();
  });

  it('should have proper ARIA landmarks defining page regions', () => {
    // Check for main landmark
    cy.get('main').should('exist');
    cy.get('main').should('have.attr', 'role', 'main').or('not.have.attr', 'role');

    // Check for navigation landmark
    cy.get('nav').should('exist');
    cy.get('nav').should('have.attr', 'role', 'navigation').or('not.have.attr', 'role');

    // Check for contentinfo landmark (footer)
    cy.get('footer').should('exist');
    cy.get('footer').should('have.attr', 'role', 'contentinfo').or('not.have.attr', 'role');

    // Check for banner landmark (header)
    cy.get('header').should('exist');
    cy.get('header').should('have.attr', 'role', 'banner').or('not.have.attr', 'role');

    // Verify landmarks are not empty
    cy.get('main').should('not.be.empty');
    cy.get('nav').should('not.be.empty');

    // Run axe accessibility checks
    cy.checkA11y(null, {
      rules: {
        'landmark-one-main': { enabled: true },
        'region': { enabled: true }
      }
    });
  });

  it('should have complementary landmark for sidebar regions', () => {
    // Check for complementary landmark (aside/sidebar)
    cy.get('aside').then(($aside) => {
      if ($aside.length > 0) {
        cy.get('aside').should('have.attr', 'role', 'complementary').or('not.have.attr', 'role');
        cy.get('aside').should('not.be.empty');
      }
    });

    // Verify all landmarks are properly labeled
    cy.get('[role="complementary"]').each(($landmark) => {
      cy.wrap($landmark).should('have.attr', 'aria-label').or('have.attr', 'aria-labelledby');
    });
  });

  it('should have search landmark when search functionality exists', () => {
    cy.get('form[role="search"]').then(($search) => {
      if ($search.length > 0) {
        cy.get('form[role="search"]').should('exist');
        cy.get('form[role="search"]').should('not.be.empty');
        cy.get('form[role="search"] input').should('exist');
      }
    });
  });

  it('should ensure landmarks do not have conflicting roles', () => {
    // Main should only appear once
    cy.get('main, [role="main"]').should('have.length.lessThan', 2);

    // Banner should only appear once
    cy.get('header[role="banner"], [role="banner"]').should('have.length.lessThan', 2);

    // Contentinfo should only appear once
    cy.get('footer[role="contentinfo"], [role="contentinfo"]').should('have.length.lessThan', 2);
  });

  it('should have proper landmark hierarchy and nesting', () => {
    // Main should not be nested inside nav
    cy.get('nav main').should('not.exist');
    cy.get('nav [role="main"]').should('not.exist');

    // Header should not contain main
    cy.get('header main').should('not.exist');
    cy.get('header [role="main"]').should('not.exist');

    // Footer should not contain main
    cy.get('footer main').should('not.exist');
    cy.get('footer [role="main"]').should('not.exist');
  });

  it('should provide accessible names for all landmarks', () => {
    // Navigation landmarks should have accessible names
    cy.get('nav').each(($nav) => {
      cy.wrap($nav).should(($element) => {
        const hasAriaLabel = $element.attr('aria-label');
        const hasAriaLabelledBy = $element.attr('aria-labelledby');
        const hasTitle = $element.attr('title');
        expect(hasAriaLabel || hasAriaLabelledBy || hasTitle || $element.find('h1, h2, h3, h4, h5, h6').length > 0).to.be.ok;
      });
    });

    // Complementary landmarks should have accessible names
    cy.get('[role="complementary"]').each(($complementary) => {
      cy.wrap($complementary).should(($element) => {
        const hasAriaLabel = $element.attr('aria-label');
        const hasAriaLabelledBy = $element.attr('aria-labelledby');
        expect(hasAriaLabel || hasAriaLabelledBy).to.be.ok;
      });
    });
  });

  it('should handle edge case of multiple navigation landmarks with distinct labels', () => {
    cy.get('nav').then(($navs) => {
      if ($navs.length > 1) {
        // Each nav should have a unique accessible name
        cy.get('nav').each(($nav, index) => {
          cy.wrap($nav).should(($element) => {
            const ariaLabel = $element.attr('aria-label');
            const ariaLabelledBy = $element.attr('aria-labelledby');
            expect(ariaLabel || ariaLabelledBy).to.exist;
          });
        });
      }
    });
  });
});
